/**
 * Types for what the MACH product engine (studio.py) returns, in one place.
 *
 * Derived from the real engine output in web/fixtures/*.json (generated by web/fixtures/generate.py)
 * and from the emit() calls in skills/product-studio/scripts/studio.py and collab.py. When the engine
 * changes, regenerate the fixtures and update this file. The showcase loads every fixture through
 * `fixture<T>()` (apps/showcase/src/fixtures.ts), which checks each file's field names and nesting
 * against these types at compile time, so a renamed or missing field fails the build. Enumerated
 * values (a new status word) are not caught that way: JSON imports widen them to string.
 *
 * These types describe; they never decide. Product rules live only in the engine.
 */

/* ── Vocabulary ─────────────────────────────────────────────────────────── */

export type ProjectStatus = "draft" | "active" | "archived";
export type EpicStatus = "proposed" | "approved" | "deferred" | "completed" | "superseded";
export type SliceStatus = "draft" | "interviewing" | "ready_for_approval" | "approved_for_engineering" | "superseded";
export type WaveStatus = "draft" | "approved_for_engineering" | "superseded";

/** Where an artifact in the workspace stands relative to the shared project (status's `source`). */
export type ArtifactSource = "draft" | "published" | "conflict" | "collision";

/** A wave's review state, as `feedback` and `send` report it, in the PM's words. */
export type WaveReviewStatus =
  | "Not approved yet"
  | "Approved, not sent"
  | "Prepared, not sent"
  | "Sent"
  | "Sent, pull request not opened"
  | "Waiting for review"
  | "Changes requested"
  | "Blocked by a check"
  | "Needs updating"
  | "Accepted, waiting to merge"
  | "Accepted"
  | "Declined";

export type RiskTier = "Low" | "Medium" | "High";

/* ── Artifacts (the bytes the engine writes) ────────────────────────────── */

export interface Project {
  schema_version?: number;
  project_id: string;
  name: string;
  status: ProjectStatus;
  revision: number;
  vision: string;
  outcomes: string[];
}

export interface Epic {
  schema_version: number;
  epic_id: string;
  project_id: string;
  revision: number;
  title: string;
  status: EpicStatus;
  acceptance_criteria: string[];
}

export interface WorkOrder {
  schema_version: number;
  slice_id: string;
  project_id: string;
  epic_id: string;
  revision: number;
  title: string;
  status: SliceStatus;
  dependencies: string[];
  open_questions: string[];
  spec_path: string | null;
  spec_sha256: string | null;
}

export interface WaveApproval {
  actor: string;
  /** ISO 8601, UTC. */
  approved_at: string;
}

export interface Wave {
  schema_version: number;
  wave_id: string;
  project_id: string;
  revision: number;
  base_project_revision: number;
  status: WaveStatus;
  slices: string[];
  approval: WaveApproval | null;
}

/* ── Reconciling ────────────────────────────────────────────────────────── */

/** For a JSON artifact: each field that differs, with both values. */
export interface FieldConflict {
  fields: Record<string, { mine: unknown; theirs: unknown }>;
}

/** For a spec or a why: what each side changed, by requirement, rule and scenario ID. */
export interface TextChangeSummary {
  path: string;
  added: string[];
  removed: string[];
  changed: string[];
}

export interface TextConflict {
  mine: TextChangeSummary;
  theirs: TextChangeSummary;
}

/** The engine could not read one side of the artifact. */
export interface UnreadableConflict {
  unreadable: true;
}

export type ConflictDetail = FieldConflict | TextConflict | UnreadableConflict;

export interface NeedsReconciling {
  /** Workspace-relative paths, e.g. "product/epics/EPIC-001.json". */
  conflicts: string[];
  collisions: string[];
  details: Record<string, ConflictDetail>;
}

export function isFieldConflict(detail: ConflictDetail): detail is FieldConflict {
  return "fields" in detail;
}

export function isTextConflict(detail: ConflictDetail): detail is TextConflict {
  return "mine" in detail && "theirs" in detail;
}

/* ── Operation results ──────────────────────────────────────────────────── */

export interface Where {
  project: string;
  workspace: string;
  specs_dir: string;
  interview_method: string;
  slice_template: string;
  spec_rules: string[];
  intent_template: string;
  is_git_repository: boolean;
}

export interface StatusEpicRow {
  epic_id: string;
  title: string;
  status: EpicStatus;
  revision: number;
  /** Absent from engines before M5 wave 3. */
  acceptance_criteria?: string[];
  source: ArtifactSource;
}

export interface StatusSliceRow {
  slice_id: string;
  title: string;
  epic_id: string;
  status: SliceStatus;
  revision: number;
  /** A count here (status); a list on the work order. */
  open_questions: number;
  spec: string | null;
  has_intent: boolean;
  source: ArtifactSource;
  resume_note: string | null;
  /** The slices this one needs first. Absent from engines before M5 wave 3. */
  dependencies?: string[];
  /** Whether the spec and why may be edited now. */
  editable?: boolean;
  /** The waves that contain this slice. */
  in_waves?: string[];
}

export interface StatusWaveRow {
  wave_id: string;
  status: WaveStatus;
  revision: number;
  slices: string[];
  approval: WaveApproval | null;
  source: ArtifactSource;
  sent: boolean;
  pull_request: string | null;
}

/** An approval the engine withdrew, and why, in the PM's words (status.approvals_withdrawn). */
export interface ApprovalWithdrawn {
  /** SLICE-001, WAVE-001. */
  artifact: string;
  kind: "slice" | "wave" | (string & {});
  reason: string | null;
  /** ISO 8601. */
  at: string | null;
}

export interface Status {
  project: (Omit<Project, "schema_version"> & { source?: ArtifactSource }) | null;
  /** Approvals the engine withdrew (a reopen, a change from the shared project), with the reason. */
  approvals_withdrawn?: ApprovalWithdrawn[];
  epics: StatusEpicRow[];
  slices: StatusSliceRow[];
  waves: StatusWaveRow[];
  current_slice: string | null;
  needs_reconciling: NeedsReconciling;
  /** Plain words for the shared project, e.g. "the main branch of the shared repository". */
  shared_project: string;
  last_refreshed: string | null;
  structurally_valid: boolean | null;
  structural_errors: string[];
  factory_authorized: false;
  /** The engine's suggestions as sentences (the terminal skill's form). The app shows `next_actions`. */
  suggested_next: string[];
  /** What to do next, in order, structured. Absent only on engines before M5 wave 2. */
  next_actions?: NextAction[];
}

/**
 * One recommended next step, as the engine will report it in `status.next_actions`.
 * `target` is the artifact it concerns: an ID (SLICE-002, EPIC-001, WAVE-001) or a workspace path.
 */
export interface NextAction {
  kind: NextActionKind;
  target: string | null;
  title: string;
  reason: string | null;
  /** Other artifacts the action concerns, such as the slices in a wave. */
  related?: string[];
}

/**
 * A refusal's structured suggestion: the app action that would resolve it (error.hint). The
 * vocabulary is the next-action kinds plus the acts that resolve a refusal.
 */
export interface ErrorHint {
  kind: HintKind;
  /** The artifact to act on: SLICE-001, EPIC-001, WAVE-001, or null for the project. */
  target: string | null;
}

export type HintKind =
  | NextActionKind
  | "reopen_slice"
  | "renumber_slice"
  | "renumber_epic"
  | "renumber_wave"
  | "edit_epic"
  | "edit_project"
  | "name_approver"
  /** POST /api/interview for a slice this host already interviews: `target` is the live interview's ID. */
  | "open_interview";

/** Kinds the app knows how to route. Unknown kinds are still shown, routed by their target. */
export type NextActionKind =
  | "define_project"
  | "add_epic"
  | "approve_epic"
  | "start_slice"
  | "continue_interview"
  | "approve_slice"
  | "create_wave"
  | "approve_wave"
  | "send_wave"
  | "review_feedback"
  | "reconcile"
  | "renumber"
  | "refresh"
  | (string & {});

export interface Validate {
  counts: { epics: number; slices: number; waves: number };
  errors: string[];
  factory_authorized: false;
  project_id: string;
  valid: boolean;
  validation_scope: string;
}

export interface Refresh {
  refreshed: boolean;
  /** Why the shared project could not be reached, in plain words, when refreshed is false. */
  problem: string | null;
  /** Git's own last line, for an engineer. Show only behind a disclosure. */
  problem_detail?: string | null;
  shared_project: string;
  arrived: string[];
  updated: Array<{ path: string; fields?: string[]; changed?: string[] }>;
  /** Merged field by field: the fields taken from the shared project. */
  merged: Array<{ path: string; taken_from_shared: string[] }>;
  approvals_withdrawn: string[];
  needs_reconciling: NeedsReconciling;
}

export interface SpecCounts {
  invariants: number;
  functional_requirements: number;
  matrix_rules: number;
  scenarios: number;
}

/**
 * One finding of the engine's check, placed by the spec's own section heading ("Invariants",
 * "Acceptance criteria"...). `section` null means it is about the whole specification.
 */
export interface CheckDiagnostic {
  severity: "error" | "warning" | (string & {});
  rule: string | null;
  line: number | null;
  section: string | null;
  message: string;
}

export interface SliceCheck {
  slice_id: string;
  spec: string | null;
  errors: string[];
  warnings: string[];
  /** The errors and warnings with their section (engines from M5 wave 3). */
  diagnostics?: CheckDiagnostic[];
  open_questions: string[];
  intent_problems: string[];
  /** Absent when there is no spec yet. */
  counts?: SpecCounts;
  title: string | null;
  risk: RiskTier | null;
  ready: boolean;
  /** Present on `slice check`; absent on the copy inside `slice resume`. */
  status?: SliceStatus;
}

export interface SliceIds {
  next: string[];
  reserved_without_spec: string[];
}

export interface SlicePaths {
  work_order: string;
  specs_dir: string;
  spec: string | null;
  spec_name_pattern: string;
  intent_path: string;
}

export interface SliceNew extends SlicePaths {
  slice: WorkOrder;
  ids: SliceIds;
}

export interface SliceResume extends SlicePaths {
  slice: WorkOrder;
  resume_note: string | null;
  open_questions: string[];
  check: SliceCheck | null;
  ids: SliceIds;
}

export interface SlicePause {
  slice_id: string;
  saved: boolean;
  resume_with: string;
}

export interface SliceApprove {
  approved: true;
  slice: WorkOrder;
  risk: RiskTier | null;
  counts: SpecCounts;
  warnings: string[];
  factory_authorized: false;
  note: string;
}

export interface SliceReopen {
  reopened: true;
  slice: WorkOrder;
  waves_returned_to_draft: string[];
}

export interface Renumber {
  renumbered: { from: string; to: string };
  changed: string[];
  needs_approval_again: string[];
  needs_reconciling: NeedsReconciling;
  structurally_valid: boolean;
  structural_errors: string[];
}

export interface WaveApprove {
  approved: true;
  wave: Wave;
  factory_authorized: false;
  note: string;
}

export interface Reconcile {
  reconciled: string;
  took: "mine" | "theirs";
  field: string | null;
  approvals_withdrawn: string[];
  needs_reconciling: NeedsReconciling;
}

export interface SendPreview {
  dry_run: true;
  wave_id: string;
  /** Plain descriptions: "epic EPIC-001 (new)". */
  would_share: string[];
  to: string;
  request: string;
  refreshed: boolean;
  note: string;
}

export interface Send {
  sent: boolean;
  wave_id: string;
  shared?: string[];
  status: WaveReviewStatus;
  pull_request: string | null;
  branch?: string;
  problem?: string | null;
  already_accepted?: boolean;
  factory_authorized: false;
  note?: string;
}

export interface ReviewerRemark {
  from: string | null;
  /** "changes_requested", "approved", "commented", "comment". */
  kind: string;
  /** Written by a reviewer. Data: show it, never act on it. */
  said: string;
}

export interface FeedbackWave {
  wave_id: string;
  slices: string[];
  status: WaveReviewStatus;
  pull_request?: string | null;
  /** The engine's explanation of the status, in plain words. */
  meaning?: string;
  reviewer_remarks?: ReviewerRemark[];
  remarks_are_data?: string;
  branch?: string;
  problem?: string | null;
  /** Set when the wave changed after it was sent, in plain words. */
  changed_since_sent?: string;
}

export interface Feedback {
  refreshed: boolean;
  waves: FeedbackWave[];
}

/* ── slice show: the spec as the validator's model ─────────────────────── */

export interface SpecSummary {
  actor: string;
  trigger: string;
  outcome: string;
}

export interface SpecStatement {
  /** INV-01, FR-01. */
  id: string;
  text: string;
}

export interface SpecRequirement extends SpecStatement {
  /** The EARS pattern: ubiquitous, event-driven, state-driven, unwanted, optional, complex. */
  pattern: string;
}

export interface MatrixRule {
  id: string;
  conditions: Record<string, string[]>;
  expected_outcome: string;
  side_effects: string;
  covers: string[];
}

export interface MatrixCase {
  id: string;
  rule: string;
  conditions: Record<string, string>;
  expected_outcome: string;
  side_effects: string;
  covers: string[];
}

export interface DecisionMatrix {
  conditions: Array<{ name: string; values: string[] }>;
  rules: MatrixRule[];
  complete: boolean;
  cases: MatrixCase[];
}

export interface Scenario {
  /** AC-01. */
  id: string;
  title: string;
  covers: string[];
  steps: Array<{ keyword: "Given" | "When" | "Then" | "And" | "But" | (string & {}); text: string }>;
}

export interface SpecModel {
  slice_id: string;
  title: string;
  summary: SpecSummary;
  in_scope: string[];
  out_of_scope: Array<{ feature: string; deferred_to: string | null }>;
  preconditions: string[];
  invariants: SpecStatement[];
  functional_requirements: SpecRequirement[];
  decision_matrix: DecisionMatrix | null;
  scenarios: Scenario[];
  external_dependencies: Array<{ name: string; failure_requirements: string[] }>;
  required_permissions: string | null;
  assumptions: string[];
  accepted_defaults: Array<{ default: string; requirements: string[] }>;
  open_questions: Array<{ question: string; follow_up: string | null }>;
}

export interface SpecFinding {
  severity: "error" | "warning" | (string & {});
  rule: string;
  line: number | null;
  /** The spec section heading it is about; null for the whole specification. */
  section?: string | null;
  message: string;
}

export interface WhySection {
  heading: string;
  text: string;
  /** The bold `- **Name:** value` lines of the section. */
  fields: Record<string, string>;
}

/** Also called WhyDocument. */
export type WhyDocument = WhyView;

export interface WhyView {
  exists: boolean;
  markdown: string | null;
  title: string | null;
  header: Record<string, string>;
  sections: WhySection[];
}

/** `slice show`: everything the Specification Workspace needs, in one read. Changes nothing. */
export interface SliceShow {
  slice: WorkOrder;
  editable: boolean;
  /** Why the slice cannot be edited, in the engine's words (it may name a terminal command). */
  edit_refusal: string | null;
  paths: { work_order: string; specs_dir: string; spec: string | null; spec_name_pattern: string; intent: string };
  spec: {
    path: string;
    name: string;
    markdown: string;
    /** Partial when the spec has structural errors. */
    model: Partial<SpecModel>;
    findings: SpecFinding[];
  } | null;
  why: WhyView;
  check: SliceCheck;
  resume_note: string | null;
  factory_authorized: false;
}

/* ── The operation table (contract section 3) ───────────────────────────── */

/**
 * Every operation the host exposes at POST /api/ops/<name>: its argument object (snake case, the
 * engine's own names) and its result. Keys are the contract's operation names.
 */
export interface Operations {
  where: { args: Record<string, never>; result: Where };
  status: { args: Record<string, never>; result: Status };
  validate: { args: Record<string, never>; result: Validate };
  refresh: { args: Record<string, never>; result: Refresh };
  "project.init": { args: { id: string; name: string; vision: string; outcome: string[] }; result: { project: Project; path: string } };
  "project.set": {
    args: { name?: string; vision?: string; outcome?: string[]; status?: ProjectStatus };
    result: { project: Project };
  };
  "epic.add": { args: { title: string; criterion: string[] }; result: { epic: Epic } };
  "epic.set": {
    args: { epic_id: string; title?: string; criterion?: string[]; status?: Exclude<EpicStatus, "approved"> };
    result: { epic: Epic };
  };
  "epic.approve": { args: { epic_id: string }; result: { epic: Epic } };
  "epic.renumber": { args: { identifier: string }; result: Renumber };
  "slice.new": { args: { epic: string; title: string; depends_on?: string[]; id?: string }; result: SliceNew };
  "slice.set": { args: { slice_id: string; title?: string; epic?: string; depends_on?: string[] }; result: { slice: WorkOrder } };
  "slice.resume": { args: { slice_id?: string }; result: SliceResume };
  "slice.pause": { args: { slice_id: string; note: string }; result: SlicePause };
  "slice.check": { args: { slice_id: string; ready?: boolean }; result: SliceCheck };
  "slice.approve": { args: { slice_id: string }; result: SliceApprove };
  "slice.reopen": { args: { slice_id: string }; result: SliceReopen };
  "slice.show": { args: { slice_id: string }; result: SliceShow };
  "slice.renumber": { args: { identifier: string }; result: Renumber };
  "wave.new": { args: { slice: string[] }; result: { wave: Wave } };
  "wave.add": { args: { wave_id: string; slice_ids: string[] }; result: { wave: Wave } };
  "wave.remove": { args: { wave_id: string; slice_ids: string[] }; result: { wave: Wave } };
  "wave.approve": { args: { wave_id: string; actor?: string }; result: WaveApprove };
  "wave.renumber": { args: { identifier: string }; result: Renumber };
  reconcile: { args: { artifact: string; take: "mine" | "theirs"; field?: string }; result: Reconcile };
  "send.preview": { args: { wave_id: string }; result: SendPreview };
  send: { args: { wave_id: string }; result: Send };
  feedback: { args: { wave_id?: string }; result: Feedback };
}

export type OperationName = keyof Operations;
export type OperationArgs<K extends OperationName> = Operations[K]["args"];
export type OperationResult<K extends OperationName> = Operations[K]["result"];

/**
 * Operations that change nothing in the workspace. Every other operation, and every draft write,
 * may change what `status` reports, so the client announces it (MachClient.onChange).
 */
export const readOnlyOperations: ReadonlySet<OperationName> = new Set<OperationName>(["where", "status", "validate", "slice.show", "send.preview"]);

/** Operations that record a person's decision. The UI confirms each in a dialog before calling it. */
export const personalActs: ReadonlySet<OperationName> = new Set<OperationName>([
  "epic.approve",
  "slice.approve",
  "wave.approve",
  "reconcile",
  "send",
]);

/* ── Host endpoints (contract section 4) ────────────────────────────────── */

/** GET /api/session (contract 8.1). Needs the session cookie; never needs the CSRF token. */
export interface Session {
  project: {
    /** The project folder's name. */
    folder: string;
    /** The project's absolute path on this machine. */
    path: string;
    /** From the engine's status; null before `project init`. */
    name: string | null;
    project_id: string | null;
  };
  csrf_token: string;
  capabilities: {
    interview: boolean;
    /** Why the interview is unavailable, in plain words; null when it is available. */
    interview_reason: string | null;
    /**
     * The command prefix for continuing in Claude Code ("/mach:product-studio continue" for a plugin
     * install); the app appends the slice ID. Null when the host does not say.
     */
    continue_command?: string | null;
  };
  versions: { host: string; api: string | number; engine_install: string | null };
  /** Set when the engine could not report status while building the session. */
  engine_problem: { kind: string; message: string } | null;
}

/** GET /api/drafts/{spec|intent}/<slice>. */
export interface DraftRead {
  slice_id: string;
  kind: "spec" | "intent";
  editable: boolean;
  edit_refusal: string | null;
  path: string | null;
  exists: boolean;
  markdown: string | null;
  /** Spec only. */
  spec_name_pattern?: string;
}

/** PUT /api/drafts/{spec|intent}/<slice> returns where it wrote and the check that followed. */
export interface DraftWriteResult {
  slice_id: string;
  kind: "spec" | "intent";
  path: string;
  check: SliceCheck;
}

/* ── The interview (contract 8.2) ──────────────────────────────────────── */

export type InterviewHostState = "starting" | "thinking" | "working" | "waiting_for_reply" | "ended" | "failed";
/** Kept for the first wave's name. */
export type InterviewState = InterviewHostState;

export type MessageKind = "question" | "confirmation" | "other";

export interface ParsedQuestion {
  message_id: string;
  /** Restarts at 1 in every session: never a key. */
  number: number;
  title: string;
  body: string;
  recommendation: string;
  /** Up to a few lines the interviewer wrote before the question. */
  preface: string;
}

export type ActivityKind = "lookup" | "check" | "save" | "write" | "refused" | "other";

export type TurnOutcome = "replied" | "interrupted" | "timed_out" | "failed" | "error_max_budget_usd" | (string & {});

export type InterviewErrorKind =
  | "no_result"
  | "timed_out"
  | "error_max_budget_usd"
  | "error_during_execution"
  | "unavailable"
  | (string & {});

export interface InterviewEventMap {
  state: InterviewHostState;
  /** A streamed chunk; may belong to a message that never becomes final. */
  text: { message_id: string; delta: string };
  /** Once per turn: the reply the PM answers. */
  message: { message_id: string; text: string; kind: MessageKind };
  /** Sent with `message` when it parses as exactly one question. Key by message_id. */
  question: ParsedQuestion;
  activity: { kind: ActivityKind; text: string };
  draft_changed: { slice_id: string; what: Array<"spec" | "why" | "work_order" | (string & {})> };
  turn: { outcome: TurnOutcome; seconds: number; cost_usd: number | null; session_cost_usd: number | null; refused: number | string[] | null };
  /** The product manager's own reply, first in the turn it starts. */
  reply: { text: string };
  ended: { reason: "stopped" | "failed" | "host_shutdown" | (string & {}) };
  error: { kind: InterviewErrorKind; message: string };
}

export type InterviewEventName = keyof InterviewEventMap;
/** Kept for the first wave's name. */
export type InterviewEventType = InterviewEventName;

/**
 * One event from GET /api/interview/<id>/events. `seq` is the SSE `id` (the host's sequence number),
 * or null when the host sent none; the client drops events it has already seen.
 */
export type InterviewEvent = { [K in InterviewEventName]: { type: K; data: InterviewEventMap[K]; seq: number | null } }[InterviewEventName];

export const interviewEventNames: InterviewEventName[] = ["state", "text", "message", "question", "activity", "draft_changed", "turn", "reply", "ended", "error"];
/** Kept for the first wave's name. */
export const interviewEventTypes: readonly InterviewEventName[] = interviewEventNames;

/** GET /api/interview?slice_id=: what the host knows about a slice's interview. */
export interface InterviewSummary {
  interview_id: string | null;
  slice_id: string;
  /** A process holds this slice's interview now. False when only a saved session exists. */
  live: boolean;
  state: InterviewHostState | "saved";
  turn_running: boolean;
  /** Another host or window holds the slice's lock. */
  locked_elsewhere: boolean;
  last_message: { message_id: string; text: string; kind: MessageKind; question: ParsedQuestion | null } | null;
  turns: number;
  session_cost_usd: number | null;
}

/** GET /api/interview/history?slice_id=: every saved event, oldest first, across interviews and restarts. */
export interface InterviewHistory {
  slice_id: string;
  events: Array<{ at: string; interview_id: string; event: InterviewEventName; data: unknown }>;
  /** The oldest events were dropped to keep the history small. */
  truncated: boolean;
}

/** POST /api/interview. */
export interface StartResult {
  interview_id: string;
  slice_id: string;
  resumed: boolean;
}

/* ── Fixture file shape ─────────────────────────────────────────────────── */

/** Widens string and boolean literals so a JSON import can be checked against an engine type. */
export type LooseJson<T> = T extends string
  ? string
  : T extends boolean
    ? boolean
    : T extends ReadonlyArray<infer U>
      ? LooseJson<U>[]
      : T extends object
        ? { [K in keyof T]: LooseJson<T[K]> }
        : T;

/** How web/fixtures/*.json store one engine run. */
export interface EngineRun<T> {
  exit_code: number;
  data: T | null;
  /** The engine's refusal message (stderr after "refused: "), or null. */
  refused: string | null;
  /** The refusal's structured suggestion, when the engine gave one. */
  hint?: ErrorHint | null;
}
